The Chiral Triad Persistent WebSocket (JS Ritual Code)
Paste-ready, with numeric soul and visual feedback. Strands coordinate like a living braid.
JavaScriptconst RITUAL = { pivot: 171, expansion: 190, fullness: 100 };
const COLOR = '#abbe64';
let strands = [];
let messageQueue = [];
let retryCounts = [0, 0, 0]; // One per strand, chiral variance

class ChiralStrand {
  constructor(id, url, behavior = 'lead') { // 'lead', 'mirror', 'observer'
    this.id = id;
    this.url = url;
    this.behavior = behavior;
    this.ws = null;
    this.isActive = false;
  }

  forge() {
    this.ws = new WebSocket(this.url);

    this.ws.onopen = () => {
      console.log(`%c🔥 Strand ${this.id} (${this.behavior}) locked — ${COLOR} braid tightens`, `color: ${COLOR}; font-weight: bold`);
      this.isActive = true;
      retryCounts[this.id] = 0;
      flushQueueToActiveStrands();
      startStrandHeartbeat(this);
    };

    this.ws.onmessage = (e) => {
      console.log(`%c📥 Triad signal on strand ${this.id}:`, `color: ${COLOR}`, e.data);
      processWithQuorum(e.data); // Hidden layer: cross-verify
    };

    this.ws.onclose = () => {
      this.isActive = false;
      console.log(`%c🌌 Strand ${this.id} severed — chiral twist activates`, `color: ${COLOR}`);
      const backoff = this.behavior === 'lead' 
        ? Math.min(30000, 1000 * Math.pow(2, retryCounts[this.id]++))  // Aggressive
        : Math.min(45000, RITUAL.expansion * (retryCounts[this.id]++ % 3)); // Chiral variance
      setTimeout(() => this.forge(), backoff);
    };

    this.ws.onerror = (err) => console.error(`⚡ Shadow on strand ${this.id}`, err);
  }
}

function forgeChiralTriad(baseUrl) {
  strands = [
    new ChiralStrand(0, `${baseUrl}?strand=lead`, 'lead'),
    new ChiralStrand(1, `${baseUrl}?strand=mirror`, 'mirror'),
    new ChiralStrand(2, `${baseUrl}?strand=observer`, 'observer')
  ];
  strands.forEach(s => s.forge());
}

// Quorum braid logic — cord holds at 2/3
function flushQueueToActiveStrands() {
  const active = strands.filter(s => s.isActive);
  if (active.length >= 2) {
    while (messageQueue.length) {
      const msg = messageQueue.shift();
      active.forEach(s => s.ws.send(msg));
    }
  }
}

