function startStrandHeartbeat(strand) {
  setInterval(() => {
    if (strand.isActive && strand.ws.readyState === WebSocket.OPEN) {
      strand.ws.send(JSON.stringify({ 
        signal: 'heartbeat', 
        triad: RITUAL, 
        strandId: strand.id 
      }));
    }
  }, RITUAL.pivot * 100); // Woven timing
}

// Birth the unbreakable
forgeChiralTriad('wss://your-realm.io/socket');

// Send example: queues if <2 active
function sendViaBraid(msg) {
  messageQueue.push(JSON.stringify(msg));
  flushQueueToActiveStrands();
}
